const input = $json;
const prId =
  input.purchase_request_id ||
  input.id ||
  input.pr_id;

if (!prId) {
  throw new Error('Workflow 2 requires purchase_request_id');
}

return [{
  json: {
    purchase_request_id: String(prId)
  }
}];

if (!$json.id) {
  throw new Error('Purchase request not found.');
}

if ($json.status !== 'sourcing') {
  throw new Error(`PR ${$json.id} is not ready for Workflow 2. Expected status=sourcing, got ${$json.status}`);
}

return [{
  json: {
    ...$json,
    purchase_request_id: $json.id
  }
}];

for (const item of items) {
  const keys = Object.keys(item.binary || {});
  if (!keys.length) continue;

  const firstKey = keys[0];
  const firstFile = item.binary[firstKey];

  item.binary = {
    ...item.binary,
    data: firstFile
  };

  item.json.quote_file_name =
    firstFile.fileName ||
    `quotation-${item.json.id || Date.now()}.pdf`;
}
return items;

return items.map(item => ({
  json: {
    quote_text:
      item.json.text ||
      item.json.content ||
      JSON.stringify(item.json),
    source_type: 'pdf'
  }
}));

return items.map(item => {
  const j = item.json || {};
  const body =
    j.textPlain ||
    j.text ||
    j.snippet ||
    j.body ||
    j.textHtml ||
    '';

  return {
    json: {
      quote_text: String(body),
      source_type: 'email_body'
    }
  };
});

const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error('Gemini returned no quotation extraction.');
}

let q;
try {
  q = JSON.parse(raw);
} catch (e) {
  throw new Error(`Gemini quotation JSON could not be parsed: ${raw}`);
}

if (!Number.isFinite(Number(q.price)) || Number(q.price) <= 0) {
  throw new Error('Invalid or missing quotation price.');
}

if (!Number.isFinite(Number(q.delivery_days)) || Number(q.delivery_days) < 0) {
  throw new Error('Invalid delivery_days.');
}

q.price = Number(q.price);
q.delivery_days = Number(q.delivery_days);
q.warranty_months = Number(q.warranty_months || 0);
q.specifications_match = Boolean(q.specifications_match);

return [{
  json: {
    ...q,
    purchase_request_id: $('Normalize Input').first().json.purchase_request_id,
    specifications: {
      match: q.specifications_match,
      deviations: q.deviations || [],
      missing_information: q.missing_information || [],
      currency: q.currency || 'PKR',
      summary: q.summary || ''
    }
  }
}];

