return [{
  json: {
    purchase_request_id: $('Normalize Input').first().json.purchase_request_id,
    quotes_saved: items.length
  }
}];

if (!items.length) {
  throw new Error('No quotations found for comparison.');
}

function specsObject(v) {
  if (v && typeof v === 'object') return v;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (_) {}
  }
  return {};
}

const rows = items.map(i => ({
  ...i.json,
  price_num: Number(i.json.price || 0),
  delivery_num: Number(i.json.delivery_days || 0),
  warranty_num: Number(i.json.warranty || 0),
  specs_obj: specsObject(i.json.specifications)
}));

const positivePrices = rows.map(r => r.price_num).filter(v => v > 0);
const positiveDelivery = rows.map(r => r.delivery_num).filter(v => v > 0);
const warranties = rows.map(r => r.warranty_num).filter(v => v >= 0);

const minPrice = Math.min(...positivePrices);
const minDelivery = positiveDelivery.length ? Math.min(...positiveDelivery) : 0;
const maxWarranty = warranties.length ? Math.max(...warranties) : 0;

return rows.map(r => {
  const priceScore = r.price_num > 0 ? (minPrice / r.price_num) * 40 : 0;
  const deliveryScore =
    r.delivery_num > 0 && minDelivery > 0
      ? (minDelivery / r.delivery_num) * 25
      : 0;

  const specMatch =
    r.specs_obj.match === true ||
    r.specs_obj.specifications_match === true;

  const specScore = specMatch ? 20 : 0;
  const warrantyScore =
    maxWarranty > 0 ? (r.warranty_num / maxWarranty) * 10 : 0;
  const paymentScore =
    String(r.payment_terms || '').trim().length > 0 ? 5 : 0;

  let total = priceScore + deliveryScore + specScore + warrantyScore + paymentScore;

  // Hard penalty for material specification mismatch.
  if (!specMatch) total = Math.min(total, 55);

  total = Math.round(total * 100) / 100;

  return {
    json: {
      ...r,
      ai_score: total,
      score_breakdown: {
        price: Math.round(priceScore * 100) / 100,
        delivery: Math.round(deliveryScore * 100) / 100,
        specifications: specScore,
        warranty: Math.round(warrantyScore * 100) / 100,
        payment_terms: paymentScore
      }
    }
  };
});

const quotes = items
  .map(i => i.json)
  .sort((a, b) => Number(b.ai_score || 0) - Number(a.ai_score || 0));

return [{
  json: {
    purchase_request_id: $('Normalize Input').first().json.purchase_request_id,
    purchase_request: $('Validate PR for Sourcing').first().json,
    quotes
  }
}];

