const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Gemini returned no recommendation.');

let rec;
try {
  rec = JSON.parse(raw);
} catch (e) {
  throw new Error(`Recommendation JSON could not be parsed: ${raw}`);
}

const bundle = $('Build Comparison Bundle').first().json;
const quotes = bundle.quotes || [];

function specMatch(q) {
  const s = q.specifications;
  if (s && typeof s === 'object') return s.match === true || s.specifications_match === true;
  if (typeof s === 'string') {
    try {
      const p = JSON.parse(s);
      return p.match === true || p.specifications_match === true;
    } catch (_) {}
  }
  return false;
}

const compliant = quotes
  .filter(specMatch)
  .sort((a, b) => Number(b.ai_score || 0) - Number(a.ai_score || 0));

const recommendedExists = quotes.some(q => String(q.vendor_id) === String(rec.recommended_vendor_id));
const recommendedIsCompliant = compliant.some(q => String(q.vendor_id) === String(rec.recommended_vendor_id));

let finalVendorId = rec.recommended_vendor_id;
let finalVendorName = rec.recommended_vendor_name;
let verificationStatus = 'accepted';

if (!recommendedExists || !recommendedIsCompliant) {
  const fallback = compliant[0] || quotes[0];
  if (!fallback) throw new Error('No vendor available for deterministic fallback.');

  finalVendorId = fallback.vendor_id;
  finalVendorName =
    fallback.vendor_name ||
    fallback.vendor ||
    rec.recommended_vendor_name ||
    '';

  verificationStatus = 'overridden_by_n8n_guard';
}

const finalQuote = quotes.find(q => String(q.vendor_id) === String(finalVendorId));

return [{
  json: {
    purchase_request_id: bundle.purchase_request_id,
    recommended_vendor_id: finalVendorId,
    recommended_vendor_name: finalVendorName,
    recommendation_score: Number(finalQuote?.ai_score || 0),
    reasons: rec.reasons || [],
    risks: rec.risks || [],
    alternative_vendor_id: rec.alternative_vendor_id || '',
    alternative_vendor_name: rec.alternative_vendor_name || '',
    confidence: Math.max(0, Math.min(1, Number(rec.confidence || 0))),
    verification_status: verificationStatus,
    comparison: quotes
  }
}];

return [{
  json: {
    vendors: items.map(i => i.json),
    purchase_request_id: $('Normalize Input').first().json.purchase_request_id
  }
}];

const pr = $('Validate PR for Sourcing').first().json;

const vendors = $('Get Vendors')
  .all()
  .map(item => item.json);

const quoteText = $json.quote_text || '';
const prompt = `
You are extracting a vendor quotation for Procurea.

PURCHASE REQUEST:
${JSON.stringify(pr)}

ELIGIBLE VENDORS:
${JSON.stringify(vendors)}

QUOTATION:
${$json.quote_text}

Extract:
- vendor_id
- vendor_name
- currency
- total quoted price
- delivery_days
- warranty_months
- payment_terms
- specifications_match
- deviations
- missing_information
- short summary

Only use information actually present in the quotation.
`;

const body = {
  contents: [
    {
      parts: [
        {
          text: prompt
        }
      ]
    }
  ],
  generationConfig: {
    responseMimeType: "application/json",
    responseJsonSchema: {
      type: "object",
      properties: {
        vendor_id: { type: "integer" },
        vendor_name: { type: "string" },
        currency: { type: "string" },
        price: { type: "number" },
        delivery_days: { type: "integer" },
        warranty_months: { type: "integer" },
        payment_terms: { type: "string" },
        specifications_match: { type: "boolean" },
        deviations: {
          type: "array",
          items: { type: "string" }
        },
        missing_information: {
          type: "array",
          items: { type: "string" }
        },
        summary: { type: "string" }
      },
      required: [
        "vendor_id",
        "vendor_name",
        "currency",
        "price",
        "delivery_days",
        "warranty_months",
        "payment_terms",
        "specifications_match",
        "deviations",
        "missing_information",
        "summary"
      ]
    }
  }
};

return {
  json: {
    ...$json,
    gemini_body: JSON.stringify(body)
  }
};
